INSERT INTO kb_products VALUES('aac-big-mack','BIG/mack','BIG/mack','','','Big Mack là thiết bị giao tiếp tăng cường (AAC) đơn giản với một nút lớn. Khi nhấn, thiết bị phát ra một thông điệp đã ghi sẵn. Phù hợp cho người mới bắt đầu học giao tiếp.','BIG/mack is a simple augmentative and alternative communication (AAC) device with one large button. When pressed, the device plays a pre-recorded message. Suitable for beginners learning to communicate.','','','Big Mack là thiết bị giao tiếp tăng cường (AAC) đơn giản với một nút lớn. Khi nhấn, thiết bị phát ra một thông điệp đã ghi sẵn. Phù hợp cho người mới bắt đầu học giao tiếp.','voice-and-speech','AbleNet','aac-big-mack','Liên hệ nhà cung cấp','https://www.ablenetinc.com/tech/big-mack/','https://www.ablenetinc.com/tech/big-mack/','https://images.unsplash.com/photo-1587829741301-dc798b83add3?w=400&h=400&fit=crop','[]','','','published',1,0,'en',NULL,'2026-10-16T08:36:44.024Z','2026-10-16T08:36:44.024Z','BIG/mack is a simple augmentative and alternative communication (AAC) device with one large button. When pressed, the device plays a pre-recorded message. Suitable for beginners learning to communicate.',NULL,NULL);
INSERT INTO kb_products VALUES('aac-interact-as','Interact-AS','Interact-AS','','','Interact-AS là phần mềm giao tiếp tăng cường (AAC) cho Windows. Hỗ trợ quét và điểm nhìn, phù hợp cho người có khó khăn về vận động tinh.','Interact-AS is an augmentative and alternative communication (AAC) software for Windows. Supports scanning and eye gaze, suitable for people with motor difficulties.','','','Interact-AS là phần mềm giao tiếp tăng cường (AAC) cho Windows. Hỗ trợ quét và điểm nhìn, phù hợp cho người có khó khăn về vận động tinh.','voice-and-speech','Origin Instruments','aac-interact-as','Liên hệ nhà cung cấp','https://www.orin.com/access/interact/','https://www.orin.com/access/interact/','https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=400&h=400&fit=crop','[]','','','published',1,0,'en',NULL,'2026-10-16T08:36:44.024Z','2026-10-16T08:36:44.024Z','Interact-AS is an augmentative and alternative communication (AAC) software for Windows. Supports scanning and eye gaze, suitable for people with motor difficulties.',NULL,NULL);
INSERT INTO kb_products VALUES('aac-step-by-step','Step-by-Step','Step-by-Step','','','Step-by-Step là thiết bị giao tiếp với 3 cấp độ. Người dùng có thể ghi và phát lại 3 thông điệp khác nhau. Phù hợp để dạy trình tự và kỹ năng.','Step-by-Step is a communication device with 3 levels. Users can record and play back 3 different messages. Suitable for teaching sequences and skills.','','','Step-by-Step là thiết bị giao tiếp với 3 cấp độ. Người dùng có thể ghi và phát lại 3 thông điệp khác nhau. Phù hợp để dạy trình tự và kỹ năng.','voice-and-speech','AbleNet','aac-step-by-step','Liên hệ nhà cung cấp','https://www.ablenetinc.com/tech/step-by-step/','https://www.ablenetinc.com/tech/step-by-step/','https://images.unsplash.com/photo-1581093458791-9f3c3250a8b0?w=400&h=400&fit=crop','[]','','','published',1,0,'en',NULL,'2026-10-16T08:36:44.024Z','2026-10-16T08:36:44.024Z','Step-by-Step is a communication device with 3 levels. Users can record and play back 3 different messages. Suitable for teaching sequences and skills.',NULL,NULL);
INSERT INTO kb_products VALUES('aac-td-suppier','TD Pilot','TD Pilot','','','TD Pilot là thiết bị giao tiếp tăng cường (AAC) sử dụng công nghệ theo dõi mắt. Gắn vào iPad và cho phép người dùng điều khiển bằng mắt.','TD Pilot is an augmentative and alternative communication (AAC) device using eye-tracking technology. Attaches to iPad and allows users to control with their eyes.','','','TD Pilot là thiết bị giao tiếp tăng cường (AAC) sử dụng công nghệ theo dõi mắt. Gắn vào iPad và cho phép người dùng điều khiển bằng mắt.','voice-and-speech','Tobii Dynavox','aac-td-suppier','Liên hệ nhà cung cấp','https://www.tobiidynavox.com/devices/ipad/td-pilot/','https://www.tobiidynavox.com/devices/ipad/td-pilot/','https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=400&h=400&fit=crop','[]','','','published',1,0,'en',NULL,'2026-10-16T08:36:44.024Z','2026-10-16T08:36:44.024Z','TD Pilot is an augmentative and alternative communication (AAC) device using eye-tracking technology. Attaches to iPad and allows users to control with their eyes.',NULL,NULL);
INSERT INTO kb_products VALUES('aac-grid-pad','Grid Pad','Grid Pad','','','Grid Pad là thiết bị AAC chuyên dụng với màn hình lớn, hỗ trợ cảm ứng và điều khiển bằng mắt. Đi kèm phần mềm Grid 3.','Grid Pad is a dedicated AAC device with a large screen, supporting touch and eye control. Comes with Grid 3 software.','','','Grid Pad là thiết bị AAC chuyên dụng với màn hình lớn, hỗ trợ cảm ứng và điều khiển bằng mắt. Đi kèm phần mềm Grid 3.','voice-and-speech','Smartbox','aac-grid-pad','Liên hệ nhà cung cấp','https://www.thinksmartbox.com/products/grid-pad','https://www.thinksmartbox.com/products/grid-pad','https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?w=400&h=400&fit=crop','[]','','','published',1,0,'en',NULL,'2026-10-16T08:36:44.024Z','2026-10-16T08:36:44.024Z','Grid Pad is a dedicated AAC device with a large screen, supporting touch and eye control. Comes with Grid 3 software.',NULL,NULL);
INSERT INTO kb_products VALUES('vision-ruby-xl-hd','Kính lúp điện tử cầm tay Ruby XL HD','Ruby XL HD Handheld Electronic Magnifier','','','Kính lúp điện tử cầm tay Ruby XL HD là thiết bị hỗ trợ người có thị lực kém đọc sách, tài liệu, nhãn mác. Màn hình 5 inch HD, zoom 2x-14x, đèn LED chiếu sáng, chế độ màu tự nhiên và tương phản cao.','Ruby XL HD is a handheld electronic magnifier that helps people with low vision read books, documents, and labels. 5-inch HD screen, 2x-14x zoom, LED lighting, natural color and high contrast modes.','','','Kính lúp điện tử cầm tay Ruby XL HD là thiết bị hỗ trợ người có thị lực kém đọc sách, tài liệu, nhãn mác. Màn hình 5 inch HD, zoom 2x-14x, đèn LED chiếu sáng, chế độ màu tự nhiên và tương phản cao.','sensory-vision','Freedom Scientific','vision-ruby-xl-hd','Liên hệ nhà cung cấp','https://www.enhancedvision.com/ruby-xl-hd.html','https://www.enhancedvision.com/ruby-xl-hd.html','https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?w=400&h=400&fit=crop','[]','','','published',1,0,'en',NULL,'2026-10-16T08:36:44.024Z','2026-10-16T08:36:44.024Z','Ruby XL HD is a handheld electronic magnifier that helps people with low vision read books, documents, and labels. 5-inch HD screen, 2x-14x zoom, LED lighting, natural color and high contrast modes.',NULL,NULL);
